function buildVocabularyQuestionBank(items) {
  const grouped = {};
  items.forEach(item => {
    if (!grouped[item.difficulty]) grouped[item.difficulty] = [];
    grouped[item.difficulty].push(item);
  });

  const bank = [];
  let id = 1;

  function getDistractors(item, field) {
    const pool = grouped[item.difficulty].filter(x => x.term !== item.term);
    const seed = Array.from(item.term).reduce((s,ch)=>s+ch.charCodeAt(0),0);
    let cursor = seed % pool.length;
    const out = [];
    while (out.length < 3) {
      const value = pool[cursor % pool.length][field];
      if (value !== item[field] && !out.includes(value)) out.push(value);
      cursor += 17;
    }
    return out;
  }

  for (const item of items) {
    let options = [item.uz, ...getDistractors(item,"uz")];
    let shift = id % 4;
    options = options.slice(shift).concat(options.slice(0,shift));
    bank.push({
      id:id++, word:item.term, uz:item.uz, difficulty:item.difficulty, category:item.category,
      type:"EN→UZ",
      question:`Choose the best Uzbek meaning of '${item.term}'.`,
      options, correct:options.indexOf(item.uz),
      explanation:`'${item.term}' means '${item.uz}' in Uzbek. Remember it together with its context.`
    });

    options = [item.term, ...getDistractors(item,"term")];
    shift = id % 4;
    options = options.slice(shift).concat(options.slice(0,shift));
    bank.push({
      id:id++, word:item.term, uz:item.uz, difficulty:item.difficulty, category:item.category,
      type:"UZ→EN",
      question:`Choose the English word or phrase that matches the Uzbek meaning '${item.uz}'.`,
      options, correct:options.indexOf(item.term),
      explanation:`The English word or phrase for '${item.uz}' is '${item.term}'.`
    });

    options = [item.term, ...getDistractors(item,"term")];
    shift = id % 4;
    options = options.slice(shift).concat(options.slice(0,shift));
    bank.push({
      id:id++, word:item.term, uz:item.uz, difficulty:item.difficulty, category:item.category,
      type:"Context",
      question:(item.context || "Choose the best vocabulary item for the blank: ___").replace("___","_____"),
      options, correct:options.indexOf(item.term),
      explanation:`The best answer in this context is '${item.term}' (${item.uz}).`
    });
  }
  return bank;
}

const VOCAB_BANK = buildVocabularyQuestionBank(VOCAB_ITEMS);
